def ingest_orders(text):
    df = pd.read_csv(io.StringIO(text))
    df["order_date"] = pd.to_datetime(df["order_date"], format="%Y-%m-%d", errors="coerce")
    bad = int((df["order_date"].isna() | ~df["order_date"].between("2025-01-01", "2025-06-30")).sum())
    if bad:
        raise ValueError(f"bad rows: {bad}")
    return df


print("ok", len(ingest_orders(texts["orders"])))
try:
    ingest_orders(texts["orders"].replace("2025", "20x5", 1))
except ValueError as e:
    print(e)
